// Shared helpers for the Catch2 tests.

#pragma once

#include <array>
#include <cstddef>
#include <string>
#include <utility>
#include <vector>

#include "origamizer/mesh.hpp"

namespace test {

/// Names of the meshes in examples/meshes (generated by generate.py).
inline const std::array<const char*, 7> kExamples = {
    "tetrahedron", "cube", "octahedron", "saddle", "torus", "cylinder", "l_prism"};

inline std::string example_path(const std::string& name) {
  return std::string(ORIGAMIZER_SOURCE_DIR) + "/examples/meshes/" + name + ".obj";
}

inline origamizer::PolygonSoup make_soup(std::vector<origamizer::Point3> points,
                                         std::vector<std::vector<std::size_t>> faces) {
  return {std::move(points), std::move(faces)};
}

/// A planar polygon in z = 0, one face, vertices in the given order.
inline origamizer::PolygonSoup flat_polygon(const std::vector<std::pair<double, double>>& xy) {
  origamizer::PolygonSoup soup;
  std::vector<std::size_t> face;
  for (const auto& [x, y] : xy) {
    face.push_back(soup.points.size());
    soup.points.emplace_back(x, y, 0);
  }
  soup.faces.push_back(face);
  return soup;
}

/// Number of border halfedges, i.e. the length of all boundary loops.
inline std::size_t boundary_length(const origamizer::SurfaceMesh& mesh) {
  std::size_t count = 0;
  for (const auto h : mesh.halfedges()) {
    if (mesh.is_border(h)) ++count;
  }
  return count;
}

}  // namespace test
